//! Parity corpus test: the Rust port against the JavaScript transcription of
//! `Conductor.hx`.
//!
//! The corpus is generated by `tests/reference/generate_parity.js` from
//! `tests/reference/conductor_ref.js`, a line-by-line transcription of the Haxe
//! functions. Haxe itself cannot run on this machine (no `haxe`/hxcpp
//! toolchain), so this is a two-implementation numerical comparison rather than
//! an execution of the original binary; the Haxe source is the single reference
//! both implementations were transcribed from.
//!
//! Regenerate with:
//! `node crates/fu-timing/tests/reference/generate_parity.js`

use serde::Deserialize;

use fu_timing::bpm::{BpmChange, RejectReason, TimingEvent, TimingEventKind};
use fu_timing::BpmMap;

#[derive(Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Case {
    name: String,
    bpm: f64,
    beats_per_measure: f64,
    steps_per_beat: i32,
    events: Vec<ReferenceEvent>,
    expected: Expected,
}

#[derive(Deserialize)]
struct ReferenceEvent {
    time: f64,
    kind: String,
    params: Vec<serde_json::Value>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    changes: Vec<BpmChange>,
    rejected: Vec<ReferenceReject>,
    samples: Vec<Sample>,
    measure_length: f64,
}

#[derive(Deserialize)]
struct ReferenceReject {
    reason: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Sample {
    time: f64,
    index: isize,
    bpm: f64,
    step_float: f64,
    beat_float: f64,
    measure_float: f64,
    step: i64,
    beat: i64,
    measure: i64,
    steps_at_time: f64,
    time_at_steps: f64,
    beats_at_time: f64,
    time_at_beats: f64,
    time_at_measures: f64,
}

fn close(left: f64, right: f64) -> bool {
    let scale = left.abs().max(right.abs()).max(1.0);
    (left - right).abs() <= 1e-9 * scale
}

fn convert(event: &ReferenceEvent) -> Option<TimingEvent> {
    let number = |index: usize| event.params.get(index).and_then(serde_json::Value::as_f64);
    let kind = match event.kind.as_str() {
        "bpm" => TimingEventKind::BpmChange { bpm: number(0)? },
        "timesig" => TimingEventKind::TimeSignatureChange {
            numerator: number(0)?,
            denominator: number(1)?,
            denominator_is_steps_per_beat: event
                .params
                .get(2)
                .and_then(serde_json::Value::as_bool)
                .unwrap_or(false),
        },
        "continuous" => TimingEventKind::ContinuousBpmChange {
            bpm: number(0)?,
            steps: number(1)?,
        },
        other => panic!("unknown reference event kind '{other}'"),
    };
    Some(TimingEvent {
        time: event.time,
        kind,
    })
}

#[test]
fn rust_conductor_matches_the_reference_port() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/parity_cases.json"
    );
    let text = std::fs::read_to_string(path).expect("parity corpus is committed");
    let corpus: Corpus = serde_json::from_str(&text).expect("parity corpus is valid JSON");
    assert!(corpus.cases.len() >= 40, "corpus should be substantial");

    let mut compared_samples = 0usize;
    for case in &corpus.cases {
        let events: Vec<TimingEvent> = case.events.iter().filter_map(convert).collect();
        let map = BpmMap::from_timing_events(
            case.bpm,
            case.beats_per_measure,
            case.steps_per_beat,
            &events,
        );

        assert_eq!(
            map.changes().len(),
            case.expected.changes.len(),
            "{}: change count",
            case.name
        );
        for (actual, expected) in map.changes().iter().zip(&case.expected.changes) {
            for (label, left, right) in [
                ("song_time", actual.song_time, expected.song_time),
                ("bpm", actual.bpm, expected.bpm),
                (
                    "beats_per_measure",
                    actual.beats_per_measure,
                    expected.beats_per_measure,
                ),
                ("step_time", actual.step_time, expected.step_time),
                ("beat_time", actual.beat_time, expected.beat_time),
                ("measure_time", actual.measure_time, expected.measure_time),
                (
                    "end_song_time",
                    actual.end_song_time,
                    expected.end_song_time,
                ),
                (
                    "end_step_time",
                    actual.end_step_time,
                    expected.end_step_time,
                ),
            ] {
                assert!(
                    close(left, right),
                    "{}: change {label} {left} != {right}",
                    case.name
                );
            }
            assert_eq!(
                actual.steps_per_beat, expected.steps_per_beat,
                "{}: steps per beat",
                case.name
            );
            assert_eq!(
                actual.continuous, expected.continuous,
                "{}: continuous flag",
                case.name
            );
        }

        assert_eq!(
            map.rejected().len(),
            case.expected.rejected.len(),
            "{}: rejected event count",
            case.name
        );
        for (actual, expected) in map.rejected().iter().zip(&case.expected.rejected) {
            let expected_reason = match expected.reason.as_str() {
                "intersects" => RejectReason::IntersectsContinuousChange,
                "same-bpm" => RejectReason::ContinuousChangeToSameBpm,
                other => panic!("unknown reference reject reason '{other}'"),
            };
            assert_eq!(
                actual.reason, expected_reason,
                "{}: reject reason",
                case.name
            );
        }

        assert!(
            close(map.measure_length(), case.expected.measure_length),
            "{}: measure length",
            case.name
        );

        let mut conductor = fu_timing::Conductor::new(map.clone());
        for sample in &case.expected.samples {
            compared_samples += 1;
            let tick = conductor.update(sample.time);

            assert_eq!(
                conductor.cur_change_index(),
                sample.index,
                "{} at {} ms: change index",
                case.name,
                sample.time
            );
            for (label, left, right) in [
                ("bpm", map.bpm_at_time(sample.time), sample.bpm),
                ("step_float", conductor.cur_step_float(), sample.step_float),
                ("beat_float", conductor.cur_beat_float(), sample.beat_float),
                (
                    "measure_float",
                    conductor.cur_measure_float(),
                    sample.measure_float,
                ),
                (
                    "steps_at_time",
                    map.steps_at_time(sample.time),
                    sample.steps_at_time,
                ),
                (
                    "time_at_steps",
                    map.time_at_steps(map.steps_at_time(sample.time)),
                    sample.time_at_steps,
                ),
                (
                    "beats_at_time",
                    map.beats_at_time(sample.time),
                    sample.beats_at_time,
                ),
                (
                    "time_at_beats",
                    map.time_at_beats(map.beats_at_time(sample.time)),
                    sample.time_at_beats,
                ),
                (
                    "time_at_measures",
                    map.time_at_measures(sample.measure as f64),
                    sample.time_at_measures,
                ),
            ] {
                assert!(
                    close(left, right),
                    "{} at {} ms: {label} {left} != {right}",
                    case.name,
                    sample.time
                );
            }
            assert_eq!(
                conductor.cur_step(),
                sample.step,
                "{} at {} ms: step",
                case.name,
                sample.time
            );
            assert_eq!(
                conductor.cur_beat(),
                sample.beat,
                "{} at {} ms: beat",
                case.name,
                sample.time
            );
            assert_eq!(
                conductor.cur_measure(),
                sample.measure,
                "{} at {} ms: measure",
                case.name,
                sample.time
            );
            // Dispatch must land exactly on the reported step, whether the
            // frame moved forward across many steps or seeked backwards.
            if let Some(last) = tick.steps.last() {
                assert_eq!(
                    *last,
                    conductor.cur_step(),
                    "{} at {} ms: last dispatched step",
                    case.name,
                    sample.time
                );
            }
        }
    }

    assert!(
        compared_samples >= 400,
        "compared {compared_samples} samples"
    );
}
